```cypher
MATCH (s:Set)-[:HAS_INVENTORY]->(inv:Inventory)
WHERE inv.version = (
    SELECT MAX(i2.version)
    FROM (s)-[:HAS_INVENTORY]->(i2:Inventory)
)
MATCH (inv)-[:HAS_PART]->(p:Part {part_num: '4864b'})
WHERE EXISTS {
    MATCH (inv)-[hp:HAS_PART]->(p)
    WHERE hp.color_id = (SELECT id FROM Color WHERE name = 'Trans-Brown')
}
RETURN s.set_num;
```

```cypher
MATCH (s:Set)-[:IN_THEME]->(t:Theme)
WHERE s.year = 2015
  AND (t.name = 'Super Heroes DC'
       OR EXISTS {
         MATCH (t)-[:SUBTHEME_OF*1..]->(parent:Theme)
         WHERE parent.name = 'Super Heroes DC'
       })
RETURN count(s) AS set_count;
```

