MATCH (s:Set {set_num: '45801-1'})
WITH s,
     // Get all paths from set to parts through nested sets and minifigs
     // We need to find paths: Set ->* (Set|Minifig) -> Part
     // The multipliers along the path give us the quantity
     // We need to separate:
     // 1. Parts directly in set's inventory (path length 1: Set->Part)
     // 2. Parts from nested sets and minifigs (path length > 1)

     // First, let's get the current version of the set
     (SELECT MAX(e.version) FROM s-[:CONTAINS]->() WHERE e IS NOT NULL) AS current_version

// Direct parts in set's inventory (not nested, not minifigs)
OPTIONAL MATCH (s)-[e1:CONTAINS {version: current_version}]->(p1:Part)
WHERE e1.is_spare = FALSE
WITH s, current_version, COALESCE(SUM(e1.qty), 0) AS direct_parts_qty

// Parts from all paths through nested items
// Path pattern: Set -[:CONTAINS]-> (Set|Minifig) -[:CONTAINS*0..]-> Part
// We need to handle: s -> nested_set_or_minifig -> ... -> part
// For each path, multiply quantities

// Get all parts reachable through any nesting, with path multipliers
OPTIONAL MATCH path = (s)-[e_first:CONTAINS {version: current_version}]->(mid:Set|Minifig)-[e_rest:CONTAINS*0..10 (r, n | WHERE r.is_spare = FALSE)]->(p:Part)
WHERE e_first.is_spare = FALSE
  AND (mid:Set IS NOT NULL OR mid:Minifig)
  // Ensure we only go through Set and Minifig nodes, not direct to Part on first hop
  AND NOT (mid:Part)
  // For the rest of path, ensure we only traverse through Sets and Minifigs to reach Parts
  // Actually, let's be more careful: the pattern should be Set->(Set|Minifig)->...->Part
  // where intermediate hops go through Set or Minifig nodes

// We need to separate: direct parts vs nested parts
// Let's use a different approach: get ALL parts with their full path multiplier
// Then determine if they came directly or through nesting

WITH s, current_version, direct_parts_qty,
     // Collect all paths and their multipliers
     // For paths where first hop goes to Part: direct
     // For paths where first hop goes to Set/Minifig: nested

     // Let's restructure: match all possible paths to parts
     // and categorize by whether the immediate child is a Part or not

// Actually, let's use a cleaner approach with two separate matches
s AS set_node, direct_parts_qty

// Re-match to get nested-derived parts
MATCH (set_node:Set {set_num: '45801-1'})
OPTIONAL MATCH path = (set_node)-[e0:CONTAINS {version: current_version}]->(first:Set|Minifig)-[erest:CONTAINS*0..10 (r, n | WHERE r.is_spare = FALSE)]->(p_nested:Part)
WHERE e0.is_spare = FALSE
  AND first:Set IS NOT NULL OR first:Minifig
WITH set_node, direct_parts_qty,
     // Calculate multiplier: e0.qty * product of all erest.qty
     e0.qty * CASE WHEN length(erest) = 0 THEN 1 ELSE list_product(properties(rels(erest), 'qty')) END AS nested_multiplier,
     p_nested

WITH set_node, direct_parts_qty, COALESCE(SUM(nested_multiplier), 0) AS nested_parts_qty

// Also need to check: are there direct parts we missed? Let's verify with explicit match
MATCH (set_node:Set {set_num: '45801-1'})
WITH set_node, direct_parts_qty, nested_parts_qty,
     (SELECT MAX(e.version) FROM set_node-[:CONTAINS]->() WHERE e IS NOT NULL) AS cv

OPTIONAL MATCH (set_node)-[ed:CONTAINS {version: cv}]->(pd:Part)
WHERE ed.is_spare = FALSE
WITH set_node, nested_parts_qty, COALESCE(SUM(ed.qty), 0) AS direct_qty_verified

WITH direct_qty_verified, nested_parts_qty,
     (direct_qty_verified + nested_parts_qty) AS total_qty,
     CASE WHEN (direct_qty_verified + nested_parts_qty) = 0 THEN 0
          ELSE (nested_parts_qty * 100.0 / (direct_qty_verified + nested_parts_qty))
     END AS percentage

RETURN round(percentage * 100) / 100 AS percentage_from_nested
