```cypher
MATCH (s:Set {set_num: '45801-1'})
WITH s, (SELECT MAX(e.version) FROM s-[:CONTAINS]->() WHERE e IS NOT NULL) AS current_version

// Get direct parts quantity (parts listed directly in set's inventory)
OPTIONAL MATCH (s)-[e_direct:CONTAINS {version: current_version}]->(p_direct:Part)
WHERE e_direct.is_spare = FALSE
WITH s, current_version, COALESCE(SUM(e_direct.qty), 0) AS direct_parts_qty

// Get nested-derived parts: paths through Set or Minifig to reach parts
OPTIONAL MATCH path = (s)-[e0:CONTAINS {version: current_version}]->(mid:Set|Minifig)-[erest:CONTAINS*0..10 (r, n | WHERE r.is_spare = FALSE)]->(p_nested:Part)
WHERE e0.is_spare = FALSE
WITH s, direct_parts_qty,
     e0.qty * CASE WHEN length(erest) = 0 THEN 1 ELSE list_product(properties(rels(erest), 'qty')) END AS path_multiplier

WITH direct_parts_qty, COALESCE(SUM(path_multiplier), 0) AS nested_parts_qty

WITH direct_parts_qty, nested_parts_qty,
     (direct_parts_qty + nested_parts_qty) AS total_parts_qty

RETURN 
  CASE WHEN total_parts_qty = 0 THEN 0.00
       ELSE round((nested_parts_qty * 100.0 / total_parts_qty) * 100) / 100
  END AS percentage_from_nested
